pub const FALLBACK_FONT_BASE64: &str = "";

pub fn fallback_font() -> Vec<u8> {
    let mut decoded = Vec::with_capacity(FALLBACK_FONT_BASE64.len() / 4 * 3);
    let mut chunk = [0_u8; 4];
    let mut used = 0;
    for byte in FALLBACK_FONT_BASE64.bytes() {
        chunk[used] = match byte {
            b'A'..=b'Z' => byte - b'A',
            b'a'..=b'z' => byte - b'a' + 26,
            b'0'..=b'9' => byte - b'0' + 52,
            b'+' => 62,
            b'/' => 63,
            b'=' => 64,
            _ => continue,
        };
        used += 1;
        if used == 4 {
            decoded.push((chunk[0] << 2) | (chunk[1] >> 4));
            if chunk[2] != 64 {
                decoded.push((chunk[1] << 4) | (chunk[2] >> 2));
            }
            if chunk[3] != 64 {
                decoded.push((chunk[2] << 6) | chunk[3]);
            }
            used = 0;
        }
    }
    decoded
}
